<?php
declare(strict_types=1);require __DIR__.'/config.php';
$sql='SELECT h.codeHab,h.description,h.taille,h.prix,h.disponible,c.libelle FROM habit h INNER JOIN categorie c ON c.codeCat=h.codeCat ORDER BY c.libelle,h.description';$rows=$db->query($sql);
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catalogue — Fedi Élégance</title><link rel="stylesheet" href="fedi.css"></head><body><header><a class="brand" href="index.php"><span>F</span> Fedi Élégance</a><nav><a href="index.php">Accueil</a><a href="ajout.php">Ajouter un habit</a><a href="location.php">Louer un habit</a></nav></header><main class="content wide"><p class="eyebrow">La collection</p><h1>Catalogue des tenues</h1><div class="table-wrap"><table><thead><tr><th>Référence</th><th>Catégorie</th><th>Description</th><th>Taille</th><th>Prix (TND)</th><th>Disponibilité</th></tr></thead><tbody><?php if($rows->num_rows===0):?><tr><td colspan="6">Aucune tenue dans le catalogue.</td></tr><?php else:while($r=$rows->fetch_assoc()):?><tr><td>#<?=(int)$r['codeHab']?></td><td><?=h($r['libelle'])?></td><td><?=h($r['description'])?></td><td><?=h($r['taille'])?></td><td><?=(int)$r['prix']?></td><td><?=$r['disponible']==='D'?'Disponible':'Loué'?></td></tr><?php endwhile;endif;?></tbody></table></div></main><footer>Fedi Élégance</footer></body></html>